package com.library.system; import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.library.common.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequiredArgsConstructor public class SystemController{private final AnnouncementMapper announcements;private final BorrowRuleMapper rules;
@GetMapping({"/api/system/announcements","/api/system/announcements/public"})public Result<List<Announcement>>list(){return Result.ok(announcements.selectList(new LambdaQueryWrapper<Announcement>().eq(Announcement::getStatus,1).orderByDesc(Announcement::getPriority).orderByDesc(Announcement::getPublishTime)));}@PostMapping("/api/system/announcements")public Result<Void>add(@RequestBody Announcement a){a.setStatus(1);a.setDeleted(0);a.setPublishTime(java.time.LocalDateTime.now());announcements.insert(a);return Result.ok();}@PutMapping("/api/system/announcements/{id}")public Result<Void>update(@PathVariable Long id,@RequestBody Announcement a){a.setId(id);announcements.updateById(a);return Result.ok();}@DeleteMapping("/api/system/announcements/{id}")public Result<Void>delete(@PathVariable Long id){announcements.deleteById(id);return Result.ok();}
@GetMapping("/api/system/rules")public Result<List<BorrowRule>>rules(){return Result.ok(rules.selectList(null));}@PutMapping("/api/system/rules/{id}")public Result<Void>rule(@PathVariable Long id,@RequestBody BorrowRule r){r.setId(id);rules.updateById(r);return Result.ok();}}
